package vn.edu.toeic.server.monitoring.signal;
import static org.assertj.core.api.Assertions.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
class AlertRulesTest {
    static final Instant C=Instant.parse("2026-10-21T01:05:00Z");
    final AlertRules engine=new AlertRules();final AlertRules.Policy policy=AlertRules.Policy.defaults();
    static AlertRules.Input event(int n){return new AlertRules.Input("A","run","signal:A:e"+n,"JAVAFX_EXAM_FOCUS","EXAM_FOCUS_CHANGED_LOST",C.minusSeconds(10),"OBSERVATION",true,0);}
    List<AlertRules.Input> events(int count){var a=new ArrayList<AlertRules.Input>();for(int n=0;n<count;n++)a.add(event(n));return a;}
    @ParameterizedTest @CsvSource({"1,INFO","2,INFO","3,REVIEW","4,REVIEW","5,REVIEW","6,HIGH_ATTENTION","7,HIGH_ATTENTION"})
    void experimentalThresholdsAreHandCounted(int count,String priority){var result=engine.evaluate("A",events(count),policy,C);assertThat(result.summaries()).hasSize(1);var s=result.summaries().getFirst();assertThat(s.priority().name()).isEqualTo(priority);assertThat(s.count()).isEqualTo(count);assertThat(s.evidence()).hasSize(Math.min(count,5));assertThat(s.evidenceLimited()).isEqualTo(count>5);assertThat(s.explanation()).contains("không phải số hành động","nguyên nhân vô hại");}
    @Test void duplicatesAndInputOrderNeverChangeCountIdentityOrResult(){var input=events(6);var expected=engine.evaluate("A",input,policy,C);input.add(event(0));Collections.reverse(input);assertThat(engine.evaluate("A",input,policy,C)).isEqualTo(expected);assertThat(engine.evaluate("A",input,policy,C)).isEqualTo(expected);}
    @Test void receivedWindowIsInclusiveLowerExclusiveCutoffAndBucketsDoNotMix(){var input=new ArrayList<AlertRules.Input>();int n=0;for(var time:List.of(C.minusSeconds(301),C.minusSeconds(300),C.minusSeconds(61),C.minusSeconds(60),C.minusNanos(1),C)){input.add(new AlertRules.Input("A","run","signal:A:e"+(n++),"JAVAFX_EXAM_FOCUS","LOST",time,"OBSERVATION",true,0));}var result=engine.evaluate("A",input,policy,C);assertThat(result.inputEvents()).isEqualTo(4);assertThat(result.summaries()).hasSize(3);assertThat(result.summaries().stream().mapToInt(AlertRules.Summary::count).sum()).isEqualTo(4);assertThat(result.summaries()).allMatch(s->s.priority()==AlertRules.Priority.INFO);}
    @Test void runAndTypeNeverCombineAndForeignAttemptFailsClosed(){var input=events(2);input.add(new AlertRules.Input("A","run2","signal:A:other","JAVAFX_EXAM_FOCUS","EXAM_FOCUS_CHANGED_LOST",C.minusSeconds(10),"OBSERVATION",true,0));input.add(new AlertRules.Input("A","run","signal:A:restore","JAVAFX_EXAM_FOCUS","EXAM_FOCUS_CHANGED_RESTORED",C.minusSeconds(10),"OBSERVATION",false,0));assertThat(engine.evaluate("A",input,policy,C).summaries()).hasSize(3).allMatch(s->s.priority()==AlertRules.Priority.INFO);assertThatThrownBy(()->engine.evaluate("B",input,policy,C)).isInstanceOf(IllegalArgumentException.class);}
    @Test void unavailableGapAndPresenceNeverBecomeBehaviorOrHighPriority(){var input=List.of(new AlertRules.Input("A","run","signal:A:u","WINDOWS_USB_STORAGE","OBSERVER_STATUS",C.minusSeconds(1),"SOURCE_UNAVAILABLE",false,0),new AlertRules.Input("A","run","signal:A:g","CLIENT_SIGNAL_DELIVERY","SIGNAL_GAP",C.minusSeconds(1),"DATA_GAP",false,9),new AlertRules.Input("A","run","presence:A:p","SERVER_PRESENCE","HEARTBEAT_INTERRUPTION",C.minusSeconds(1),"PRESENCE_INTERRUPTION",false,0));var r=engine.evaluate("A",input,policy,C);assertThat(r.gapEvents()).isEqualTo(1);assertThat(r.unavailableEvents()).isEqualTo(2);assertThat(r.summaries()).allMatch(s->s.priority()==AlertRules.Priority.REVIEW);assertThat(r.summaries()).anyMatch(s->s.dropped().equals(java.math.BigInteger.valueOf(9))&&s.explanation().contains("không biết nội dung"));assertThat(r.summaries()).anyMatch(s->s.explanation().contains("không phải bằng chứng hành vi"));}
    @Test void lateReceiptUsesServerTimeWithoutChangingOriginalClientObservation(){var signal=new vn.edu.toeic.protocol.monitoring.signal.FocusSignal("late","run",1,C.minusSeconds(86400),vn.edu.toeic.protocol.monitoring.EventOrigin.UNSPECIFIED,false,"OTHER_OR_UNKNOWN",null);var input=AlertService.typed(new SignalService.Stored(signal,"A",1,C.minusSeconds(1),"PREVIOUS_CONNECTION",false));var r=engine.evaluate("A",List.of(input),policy,C);assertThat(r.inputEvents()).isEqualTo(1);assertThat(signal.observedAt()).isEqualTo(C.minusSeconds(86400));assertThat(r.summaries().getFirst().priority()).isEqualTo(AlertRules.Priority.INFO);}
    @Test void harmlessAppSwitchIsStillOnlyAnObservationAndNoVerdict(){var r=engine.evaluate("A",events(1),policy,C);assertThat(r.summaries().getFirst().priority()).isEqualTo(AlertRules.Priority.INFO);assertThat(r.summaries().getFirst().explanation()).contains("nguyên nhân vô hại");assertThat(engine.evaluate("A",List.of(),policy,C).summaries()).isEmpty();}
    @Test void summaryCapIsExplicitAndEvidenceRemainsBounded(){var input=new ArrayList<AlertRules.Input>();for(int n=0;n<120;n++)input.add(new AlertRules.Input("A","run"+n,"signal:A:"+n,"JAVAFX_DISPLAY","DISPLAY_COUNT_OBSERVED",C.minusSeconds(1),"OBSERVATION",false,0));var r=engine.evaluate("A",input,policy,C);assertThat(r.summaries()).hasSize(100);assertThat(r.summaryLimited()).isTrue();assertThat(r.inputEvents()).isEqualTo(120);}
    @Test void invalidConfigAndInputBoundsAreRejected(){for(var bad:List.of(new int[]{0,300,3,6,200},new int[]{60,999,3,6,200},new int[]{60,300,1,6,200},new int[]{60,300,3,3,200},new int[]{60,300,3,6,201})){assertThatThrownBy(()->new AlertRules.Policy(bad[0],bad[1],bad[2],bad[3],bad[4])).isInstanceOf(IllegalArgumentException.class);}assertThatThrownBy(()->engine.evaluate("A",events(801),policy,C)).isInstanceOf(IllegalArgumentException.class);}
    @Test void conflictingIdentityCannotSilentlyChangeAnEvent(){var input=events(1);input.add(new AlertRules.Input("A","anotherRun","signal:A:e0","JAVAFX_EXAM_FOCUS","LOST",C.minusSeconds(1),"OBSERVATION",true,0));assertThatThrownBy(()->engine.evaluate("A",input,policy,C)).isInstanceOf(IllegalArgumentException.class);}
    @Test void largeGapTotalsAreExactDecimalStringsNotUnsafeJsonIntegers(){long count=vn.edu.toeic.protocol.monitoring.signal.SignalJson.MAX_INTEGER;var input=List.of(new AlertRules.Input("A","run","signal:A:g1","CLIENT_SIGNAL_DELIVERY","SIGNAL_GAP",C.minusSeconds(1),"DATA_GAP",false,count),new AlertRules.Input("A","run","signal:A:g2","CLIENT_SIGNAL_DELIVERY","SIGNAL_GAP",C.minusSeconds(1),"DATA_GAP",false,count));assertThat(engine.evaluate("A",input,policy,C).summaries().getFirst().json().get("droppedCount").getAsString()).isEqualTo(Long.toString(count*2));}
    @ParameterizedTest @CsvSource({"USB,1,INFO","USB,3,REVIEW","USB,6,HIGH_ATTENTION","FOCUS,1,INFO","FOCUS,3,REVIEW","FOCUS,6,HIGH_ATTENTION","WINDOW,1,INFO","WINDOW,3,REVIEW","WINDOW,6,HIGH_ATTENTION"})
    void actualTypedTransitionsUseSameExperimentalThresholds(String kind,int count,String expected){
        var rows=new ArrayList<AlertRules.Input>();for(int n=0;n<count;n++){
            var t=C.minusSeconds(1);var origin=vn.edu.toeic.protocol.monitoring.EventOrigin.UNSPECIFIED;
            vn.edu.toeic.protocol.monitoring.signal.Signal signal=switch(kind){
                case "USB"->new vn.edu.toeic.protocol.monitoring.signal.UsbStorageSignal("e"+n,"run",n+1,t,origin,vn.edu.toeic.protocol.monitoring.signal.UsbStorageSignal.Kind.USB_STORAGE_CONNECTED,vn.edu.toeic.protocol.monitoring.signal.UsbStorageSignal.Quality.PARTIAL,1,null);
                case "FOCUS"->new vn.edu.toeic.protocol.monitoring.signal.FocusSignal("e"+n,"run",n+1,t,origin,false,"OTHER_OR_UNKNOWN",null);
                default->new vn.edu.toeic.protocol.monitoring.signal.WindowSignal("e"+n,"run",n+1,t,origin,true,false,"CHANGED");};
            rows.add(AlertService.typed(new SignalService.Stored(signal,"A",n+1,t,"LIVE",false)));
        }
        var result=engine.evaluate("A",rows,policy,C);assertThat(result.summaries()).hasSize(1);assertThat(result.summaries().getFirst().priority().name()).isEqualTo(expected);assertThat(result.summaries().getFirst().count()).isEqualTo(count);
    }
    @Test void processClassificationRequiresExistingPolicyAndKnownNameAndLabelsMissingMetadata(){
        assertThat(AlertService.process("A","run","p","foreign-policy","chrome.exe","COMPLETE",C)).isNull();assertThat(AlertService.process("A","run","p","process-policy-v1","unknown.exe","COMPLETE",C)).isNull();
        var missing=AlertService.process("A","run","p","process-policy-v1","CHROME.EXE","UNREADABLE",C.minusSeconds(1));var result=engine.evaluate("A",List.of(missing),policy,C);assertThat(result.summaries().getFirst().ruleId()).isEqualTo("SOURCE_UNAVAILABLE");assertThat(result.summaries().getFirst().priority()).isEqualTo(AlertRules.Priority.REVIEW);
    }

    @Test void validLegacyGapCountsCannotOverflowDerivedTotal(){var input=List.of(new AlertRules.Input("A","run","process-gap:A:g1","PROCESS_QUEUE","MONITORING_GAP",C.minusSeconds(1),"DATA_GAP",false,Long.MAX_VALUE),new AlertRules.Input("A","run","process-gap:A:g2","PROCESS_QUEUE","MONITORING_GAP",C.minusSeconds(1),"DATA_GAP",false,Long.MAX_VALUE));assertThat(engine.evaluate("A",input,policy,C).summaries().getFirst().json().get("droppedCount").getAsString()).isEqualTo("18446744073709551614");}

}
